(7277050, 1133242, 124815, '<td valign="top">It is definitely a deja vu image but there is always the little detail that is so likable and true in each image of the kind. I like here the difference between the moving person seemingly without an umbrella and running to shelter and the almost static and assured reflection</td>', 'It is definitely a deja vu image but there is always the little detail that is so likable and true in each image of the kind. I like here the difference between the moving person seemingly without an umbrella and running to shelter and the almost static and assured reflection', '2014-10-24 21:48:38.000000', NULL, 1),
(7277051, 1133268, 170281, '<td valign="top">Nice approach and the colors really work.</td>', 'Nice approach and the colors really work.', '2014-10-24 21:51:30.000000', NULL, 1),
(7277052, 1133262, 124815, '<td valign="top">The blasé feel of an after work drizzle in Midtown. And boy, how we hate these huge umbrellas when it''s crowded! The tonality creates the mood.</td>', 'The blasé feel of an after work drizzle in Midtown. And boy, how we hate these huge umbrellas when it''s crowded! The tonality creates the mood.', '2014-10-24 21:54:11.000000', NULL, 1),
(7277054, 1133251, 124815, '<td valign="top">So crisp and perfect that it looks like a collage; it''s telling a heroic story</td>', 'So crisp and perfect that it looks like a collage; it''s telling a heroic story', '2014-10-24 21:55:35.000000', NULL, 1),
(7277122, 1132769, 124982, '<td valign="top">Nice enough composition, but the choice of HDR doesn''t really do anything for it - HDR for HDR''s sake, rather than a subject that <i>needs</i> it.</td>', 'Nice enough composition, but the choice of HDR doesn''t really do anything for it - HDR for HDR''s sake, rather than a subject that needs it.', '2014-10-25 12:58:07.000000', NULL, 1),
