(7278289, 1133052, 13077, '<td valign="top">Clever lego-man. I like the little bit of water coming down.</td>', 'Clever lego-man. I like the little bit of water coming down.', '2014-10-30 10:28:14.000000', NULL, 1),
(7278290, 1133068, 150277, '<td valign="top">Wonderful submission for the challenge, I love the pop of color.  10 from me.<br/><br/><i>Message edited by author 2014-10-31 14:06:22.</i></td>', 'Wonderful submission for the challenge, I love the pop of color.  10 from me.', '2014-10-30 10:38:47.000000', '2014-10-31 14:06:22.000000', 1),
