(7278292, 1133268, 150277, '<td valign="top">Beautiful.  Pretty colors and lighting and great creativity.</td>', 'Beautiful.  Pretty colors and lighting and great creativity.', '2014-10-30 10:39:22.000000', NULL, 1),
(7278293, 1133220, 150277, '<td valign="top">I like the power of that red and the wonderfully huge umbrellas; I also enjoyed the hint at a pattern and the spontaneous scene.</td>', 'I like the power of that red and the wonderfully huge umbrellas; I also enjoyed the hint at a pattern and the spontaneous scene.', '2014-10-30 10:40:12.000000', NULL, 1),
(7278294, 1133251, 150277, '<td valign="top">I like the strong yellow in the image and the odd scene against a city backdrop.</td>', 'I like the strong yellow in the image and the odd scene against a city backdrop.', '2014-10-30 10:41:07.000000', NULL, 1),
(7278295, 1133310, 150277, '<td valign="top">So pretty - I like the lighting and that splash of purple.</td>', 'So pretty - I like the lighting and that splash of purple.', '2014-10-30 10:41:32.000000', NULL, 1),
(7278297, 1133052, 150277, '<td valign="top">Love it!  Nice timing to catch the splash.</td>', 'Love it!  Nice timing to catch the splash.', '2014-10-30 10:42:30.000000', NULL, 1),
(7278298, 1132917, 150277, '<td valign="top">Difficult to truly know this is an umbrella, but assuming it is just a great image.  I tend to be a light rather than a dark person, and the yellow mixed with black looks a bit ''dirty'' to me.  But IMHO this is really an amazing submission for the challenge - beautifully executed.</td>', 'Difficult to truly know this is an umbrella, but assuming it is just a great image.  I tend to be a light rather than a dark person, and the yellow mixed with black looks a bit ''dirty'' to me.  But IMHO this is really an amazing submission for the challenge - beautifully executed.', '2014-10-30 10:44:28.000000', NULL, 1),
(7278300, 1133050, 13077, '<td valign="top">Very colorful. I wonder if a slightly lighter colored background might have looked better, though? Her dark hair sort of disappears into the background as is.</td>', 'Very colorful. I wonder if a slightly lighter colored background might have looked better, though? Her dark hair sort of disappears into the background as is.', '2014-10-30 11:21:53.000000', NULL, 1),
(7278301, 1132769, 13077, '<td valign="top">Pleasant enough scene with good soft lighting, but nothing about it is all that interesting. I think having a person shopping at the veggie racks would have improved it a lot.</td>', 'Pleasant enough scene with good soft lighting, but nothing about it is all that interesting. I think having a person shopping at the veggie racks would have improved it a lot.', '2014-10-30 11:25:43.000000', NULL, 1),
(7278306, 1132869, 177111, '<td valign="top">love it.</td>', 'love it.', '2014-10-30 12:09:08.000000', NULL, 1),
