(7278318, 1133268, 13077, '<td valign="top">Very nice. Must have been a lot of trouble dragging that big frame out there, but it was worth it, great photo.</td>', 'Very nice. Must have been a lot of trouble dragging that big frame out there, but it was worth it, great photo.', '2014-10-30 12:52:50.000000', NULL, 1),
(7278321, 1133301, 13077, '<td valign="top">I like the projected light and shadows from the window, and the way it progresses from solid black to nice bold shapes and then faint delicate highlights going from left to right.</td>', 'I like the projected light and shadows from the window, and the way it progresses from solid black to nice bold shapes and then faint delicate highlights going from left to right.', '2014-10-30 13:12:36.000000', NULL, 1),
