(7278323, 1133262, 13077, '<td valign="top">Does a good job of conveying the atmosphere of a cold &amp; rainy day, especially with the haze.</td>', 'Does a good job of conveying the atmosphere of a cold & rainy day, especially with the haze.', '2014-10-30 13:20:25.000000', NULL, 1),
(7278327, 1133299, 13077, '<td valign="top">It''s an interesting scene, and the lack of focus brings it pretty far into the abstract realm, letting the viewer appreciate the composition, shapes and tones. I''m guessing a lot of voters will have seen the lack of focus and given you 1''s and 2''s, though...</td>', 'It''s an interesting scene, and the lack of focus brings it pretty far into the abstract realm, letting the viewer appreciate the composition, shapes and tones. I''m guessing a lot of voters will have seen the lack of focus and given you 1''s and 2''s, though...', '2014-10-30 13:32:29.000000', NULL, 1),
(7278328, 1132917, 13077, '<td valign="top">Was this shot through a kaleidoscope? It''s got some interesting patterns and everything, but I don''t get a strong ''umbrella'' impression from it, even if that''s what the subject actually was.</td>', 'Was this shot through a kaleidoscope? It''s got some interesting patterns and everything, but I don''t get a strong ''umbrella'' impression from it, even if that''s what the subject actually was.', '2014-10-30 13:33:43.000000', NULL, 1),
(7278329, 1133321, 13077, '<td valign="top">I like this arrangement of various weathered textures and shapes. Well composed.</td>', 'I like this arrangement of various weathered textures and shapes. Well composed.', '2014-10-30 13:34:52.000000', NULL, 1),
(7278330, 1133068, 13077, '<td valign="top">Very strong composition and good light, and the photo is well suited to the shallow DOF. I like it.</td>', 'Very strong composition and good light, and the photo is well suited to the shallow DOF. I like it.', '2014-10-30 13:35:41.000000', NULL, 1),
(7278331, 1133253, 13077, '<td valign="top">Very nice. Simple, naturally gritty, and excellent composition and processing.</td>', 'Very nice. Simple, naturally gritty, and excellent composition and processing.', '2014-10-30 13:36:21.000000', NULL, 1),
(7278332, 1133319, 13077, '<td valign="top">I like the composition and the various textures in different parts of the water, and good title as well.</td>', 'I like the composition and the various textures in different parts of the water, and good title as well.', '2014-10-30 13:37:13.000000', NULL, 1),
(7278333, 1133260, 13077, '<td valign="top">Well composed and exposed, and full of life. I like it.</td>', 'Well composed and exposed, and full of life. I like it.', '2014-10-30 13:39:01.000000', NULL, 1),
(7278334, 1132765, 13077, '<td valign="top">Well composed and exposed. Meets the challenge well, and has lots of strong shapes and patterns.</td>', 'Well composed and exposed. Meets the challenge well, and has lots of strong shapes and patterns.', '2014-10-30 13:39:40.000000', NULL, 1),
(7278335, 1133295, 13077, '<td valign="top">Great point of view here. Simple but interesting street scene. The giant rat might have been interesting to see from a low-angle street-level view, but then again from this angle the fact that he''s a rat in a cage is fascinating.</td>', 'Great point of view here. Simple but interesting street scene. The giant rat might have been interesting to see from a low-angle street-level view, but then again from this angle the fact that he''s a rat in a cage is fascinating.', '2014-10-30 13:41:33.000000', NULL, 1),
